import sys
sys.setrecursionlimit(5000)
n, m = map(int, input().split())
g = {i: [] for i in range(1, n + 1)}
for _ in range(m):
    a, b = map(int, input().split())
    g[a].append(b)
reach = {i: set() for i in g}
for i in g:
    st = list(g[i])
    while st:
        y = st.pop()
        if y not in reach[i]:
            reach[i].add(y)
            st.extend(g[y])
cyc = sorted(i for i in g if i in reach[i])
print("DEADLOCK" if cyc else "SAFE")

